  bool AutoAllowed(){return !AutomationSmoke()&&(!Debug.isDebugBuild||Application.platform!=RuntimePlatform.WebGLPlayer||!Application.absoluteURL.Contains("fx-smoke=")||Application.absoluteURL.Contains("fx-smoke=autosave")||Application.absoluteURL.Contains("fx-smoke=savefail")||Application.absoluteURL.Contains("fx-smoke=wave-savefail")||Application.absoluteURL.Contains("fx-smoke=warning-geometry"));}
