  bool waveStartSaveFailed,autoSaveWarning;float debugSaveWarningNext,debugManualFeedbackNext,saveSuccessUntil,prepSaveSuccessUntil,saveBlockedUntil;int saveFeedback,prepSaveFeedback;bool debugManualSaveFailureInjected,debugWarningGeometryLogged;
  void BindBattle(){waveStartSaveFailed=false;autoSaveWarning=false;debugSaveWarningNext=0;debugManualFeedbackNext=0;saveFeedback=0;prepSaveFeedback=0;saveSuccessUntil=0;prepSaveSuccessUntil=0;saveBlockedUntil=0;debugManualSaveFailureInjected=false;debugWarningGeometryLogged=false;autoSaveRetry.Reset();quickClear=false;decidedSeen=false;decidedUntil=0;debugClearBannerPhase=-1;pendingTouchSlot=-1;autoClearWave=-1;clearedWave=-1;progressHint.Reset();battle.ReinforcementOffered=b=>{aiming=false;queued=null;held.Clear();notice="웨이브 시작 전 증원을 선택하세요.";if(AutoAllowed())try{if(Debug.isDebugBuild&&Application.platform==RuntimePlatform.WebGLPlayer&&Application.absoluteURL.Contains("fx-smoke=savefail")){Debug.Log("REINFORCEMENT_SAVEFAIL "+string.Join(",",Array.ConvertAll(b.Reinforcements.Choices(),c=>c.ToString())));throw new InvalidOperationException("Injected save failure");}CombatStore.SaveAuto(b,waveCheckpoint,(int)SimulationSpeed);autoSaveRetry.Success();waveStartSaveFailed=false;autoSaveWarning=false;autoOwned=true;}catch(Exception){waveStartSaveFailed=true;notice="증원 선택 자동 저장 실패 · 선택지를 확인하세요.";}};battle.WaveStarted=b=>{waveCheckpoint=b.CopyCombat();if(AutoAllowed())try{if(Debug.isDebugBuild&&Application.platform==RuntimePlatform.WebGLPlayer&&(Application.absoluteURL.Contains("fx-smoke=wave-savefail")||Application.absoluteURL.Contains("fx-smoke=warning-geometry"))){Debug.Log("WAVE_SAVEFAIL_INJECTED");throw new InvalidOperationException("Injected wave save failure");}CombatStore.SaveAuto(b,waveCheckpoint,(int)SimulationSpeed);autoSaveRetry.Success();waveStartSaveFailed=false;autoSaveWarning=false;autoOwned=true;if(Debug.isDebugBuild&&Application.platform==RuntimePlatform.WebGLPlayer&&Application.absoluteURL.Contains("fx-smoke=autosave"))Debug.Log("AUTO_SAVE "+b.Wave+" "+b.Gold);}catch(Exception){waveStartSaveFailed=true;}};}
  bool SideLayout(){return Screen.width>=480&&Screen.height<=Screen.width&&((Screen.width<1000&&Screen.height<=480)||Screen.width<850||Screen.width>=1500);}
  bool LargeSide(){return Screen.width>=1500&&Screen.height>=650;}
  float SideFactor(){return LargeSide()?Mathf.Clamp(Screen.width/1920f,1,1.5f):1;}
  float SidePanelWidth(){return LargeSide()?360*Mathf.Min(2f,Screen.height/1080f):190;}
  bool WindowTooSmall(){return Screen.width<320||Screen.height<300;}
  void Layout(){if(SideLayout()){float mapWidth=Screen.width-SidePanelWidth(),header=LargeSide()?72*Mathf.Min(2f,Screen.height/720f):72;scale=Mathf.Min(mapWidth/1280f,Mathf.Max(1,Screen.height-header-4)/768f);ox=(mapWidth-1280*scale)/2;oy=header+Mathf.Max(0,Screen.height-header-768*scale)/2;return;}scale=Mathf.Min(Screen.width/1280f,Mathf.Max(1,Screen.height-190)/768f);ox=(Screen.width-1280*scale)/2;oy=Screen.width<700&&Screen.height>Screen.width?84:72+(Mathf.Max(0,Screen.height-190-768*scale))/2;}
  Point Map(Vector2 screen){return new Point((screen.x-ox)/scale,(screen.y-oy)/scale);}
  bool OnMap(Point p){return p.X>=0&&p.X<=1280&&p.Y>=0&&p.Y<=768;}
  float EffectiveSpeed {get{return quickClear&&battle.Decided?6:SimulationSpeed;}}
  readonly List<Cue> frameCues=new List<Cue>();
  // Clamp wall time before scaling, then preserve every cue across bounded steps.
  void AdvanceBattle(float wallDelta,float speed){
   double remaining=Math.Min(wallDelta,.25f)*speed;
   frameCues.Clear();
   while(remaining>0&&battle.Phase==Phase.Fighting){double step=Math.Min(remaining,.25);battle.Step(step);frameCues.AddRange(battle.Cues);remaining-=step;}
   battle.Cues.Clear();battle.Cues.AddRange(frameCues);
  }
  void Update(){Layout();sound.MusicState(battle.Phase==Phase.Fighting,paused||aiming||branchMenu||toolsMenu||guideMenu||fieldMenu||titleMenu||battle.ReinforcementPending,battle.Enemies.Count,battle.Decided);if(saleSlot>=0&&(selected!=saleSlot||battle.Phase!=Phase.Fighting||Time.unscaledTime>=saleUntil))saleSlot=-1;
   // OnGUI handles pointer/keyboard once using Event.Use; no parallel touch listener.
