  bool LoadCombat(bool automatic=false){try{Battle loaded,savedWave;int speed;if(automatic)CombatStore.LoadAuto(out loaded,out savedWave,out speed);else CombatStore.Load(out loaded,out savedWave,out speed);autoOwned=automatic;if(Debug.isDebugBuild&&Application.platform==RuntimePlatform.WebGLPlayer&&automatic)Debug.Log("AUTO_LOAD "+loaded.Wave+" "+loaded.Gold+" "+CombatStore.Exists);checkpoint=null;waveCheckpoint=savedWave;battle=loaded;BindBattle();visuals.Clear();selected=-1;inspectedEnemy=-1;paused=true;aiming=false;queued=null;earlyUntil=0;panelScroll=Vector2.zero;SimulationSpeed=speed;notice=battle.RulesVersion==0?"이전 난도 규칙의 전투를 복원했습니다.":"전투 복원 완료 · 이어가기를 누르세요.";return true;}catch(Exception){notice="전투 저장을 읽지 못했습니다. 현재 상태는 그대로 유지됩니다.";return false;}}
  bool LoadPrep(){try{Battle saved=PreparationStore.Load();checkpoint=null;waveCheckpoint=null;battle=saved;BindBattle();visuals.Clear();selected=-1;inspectedEnemy=-1;paused=false;aiming=false;queued=null;SimulationSpeed=1;notice="저장한 준비를 불러왔습니다.";return true;}catch(Exception){notice="저장된 준비를 읽지 못했습니다. 현재 상태는 그대로 유지됩니다.";return false;}}
  void RetryCheckpoint(){if(checkpoint==null&&waveCheckpoint==null)return;try{bool combat=waveCheckpoint!=null;battle=combat?waveCheckpoint.CopyCombat():Battle.RestorePreparation(checkpoint);BindBattle();visuals.Clear();selected=-1;inspectedEnemy=-1;paused=combat;aiming=false;queued=null;earlyUntil=0;panelScroll=Vector2.zero;SimulationSpeed=1;notice=combat?battle.Wave+"웨이브 시작으로 복원 · 편성 후 이어가세요.":"시작 준비로 복원 · 병력을 조정하고 시작하세요.";if(Debug.isDebugBuild&&Application.platform==RuntimePlatform.WebGLPlayer&&Application.absoluteURL.Contains("fx-smoke=surrender")&&combat&&paused)Debug.Log("SURRENDER_RETRY_OK");}catch(Exception){notice="최근 상태를 복원하지 못했습니다. 새 전투로 다시 시작하세요.";}}
  void UpgradeCue(Unit unit){sound.Play("upgrade");if(unit!=null&&visuals.Count<160)visuals.Add(new VisualCue{Cue=new Cue("upgrade",battle.Field.Slots[unit.Slot]){Slot=unit.Slot}});}
  void ChooseTroop(int kind){if(tutorialStage==1){tutorialStage=2;if(Debug.isDebugBuild&&Application.platform==RuntimePlatform.WebGLPlayer)Debug.Log("TUTORIAL_STAGE 2");}pendingTouchSlot=-1;inspectedEnemy=-1;troop=kind;notice=kind==0?"검사 · 가까운 적 최대 3명 공격":kind==1?(battle.FastWaves&&!battle.HardWaves?"궁수 · 질주·방패 피해 1.5배":"궁수 · 먼 적 하나 공격 · 방어력 7 무시 · 목표 선택"):kind==2?"폭탄병 · 붉은 원 안은 공격 불가, 바깥에서 범위 피해":kind==3?"서리 · 이동 둔화 보조 · 공격 병력과 함께 배치":"기술자 · 직접 공격하지 않으며 주변 병력을 지원";}
  void StartWave(){if(battle.Phase!=Phase.Preparation)return;if(!battle.Units.Exists(u=>u.Kind!=4)){notice=battle.Units.Count==0?"먼저 공격 병력을 배치하세요.":"기술자는 직접 공격하지 않습니다. 공격 병력을 배치하세요.";return;}var beforeWave=battle.SavePreparation();if(battle.Start()){if(tutorialStage>0&&tutorialStage<=3){FinishTutorial();tutorialStage=4;tutorialKillUntil=0;if(Debug.isDebugBuild&&Application.platform==RuntimePlatform.WebGLPlayer)Debug.Log("TUTORIAL_START");}pendingTouchSlot=-1;checkpoint=beforeWave;sound.Play("wave");notice=battle.Wave+"웨이브 시작 · 적을 막으세요.";}}
  string SaleLabel(Unit unit){if(unit==null)return "선택 병력 판매";if(battle.Phase==Phase.Fighting&&saleSlot==selected&&Time.unscaledTime<saleUntil)return "재확인 -"+(unit.Invested-Battle.SaleRefund(unit))+"G";return "판매 +"+Battle.SaleRefund(unit)+"G";}
  void SellSelected(){var unit=battle.At(selected);if(unit==null)return;int loss=unit.Invested-Battle.SaleRefund(unit);if(battle.Phase==Phase.Fighting&&loss>0){float now=Time.unscaledTime;if(saleSlot!=selected||now>=saleUntil){saleSlot=selected;saleUntil=now+4;saleReadyAt=now+.3f;notice="한 번 더 눌러 판매 -"+loss+"G";return;}if(now<saleReadyAt)return;}saleSlot=-1;string name=Balance.Troops[unit.Kind].Name;int before=battle.Gold;if(battle.Sell(selected)){notice=name+" 판매 · +"+(battle.Gold-before)+"G";if(Debug.isDebugBuild&&Application.platform==RuntimePlatform.WebGLPlayer&&Application.absoluteURL.Contains("fx-smoke=saleui"))Debug.Log("SALE_UI "+battle.Gold+" "+battle.Units.Count);}else notice="지금은 병력을 판매할 수 없습니다.";}
  static string PriorityName(int value){return value==1?"체력 높은 적":value==2?"빠른 적":value==3?"대장 우선":"앞선 적";}
  string PlacementNotice(){if(hoverSlot>=0&&troop==4&&!aiming&&!branchMenu&&!toolsMenu&&!fieldMenu&&!guideMenu){Point p=battle.Field.Slots[hoverSlot];int newlySupported=0,alreadySupported=0;foreach(var ally in battle.Units)if(ally.Kind!=4&&Point.Distance(p,battle.Field.Slots[ally.Slot])<=Balance.Troops[4].Range){double haste,bonusDamage;battle.SupportBonuses(ally,out haste,out bonusDamage);if(haste<.25)newlySupported++;else alreadySupported++;}return "새 지원 "+newlySupported+"명 · 기존 지원 "+alreadySupported+"명";}if(hoverSlot>=0&&troop<4&&!aiming&&!branchMenu&&!toolsMenu&&!fieldMenu&&!guideMenu){int grade=PlacementCoverage.Grade(battle.FieldIndex,troop,hoverSlot);if(grade>=0)return "경로 사거리 · "+(grade==2?"상":grade==1?"중":"하");}bool hasRecommended=false;for(int i=0;i<battle.Field.Slots.Length;i++)if(battle.At(i)==null&&PlacementCoverage.Grade(battle.FieldIndex,troop,i)==2){hasRecommended=true;break;}return notice+(Screen.width>=1000&&battle.FieldIndex>0&&troop<4&&!aiming&&hasRecommended?" · 초록: 길이 많이 닿는 자리":"");}
  string UnitNotice(Unit unit){string name=Balance.Troops[unit.Kind].Name+" Lv"+unit.Level;if(unit.Kind==4)return name+(unit.Stun>0?" · 기절 중 · 지원 중단":" · 범위 "+Math.Round(Battle.UnitRange(unit))+" · 속도 +"+(unit.Level>=2?35:25)+"%"+(unit.Branch==2?" · 피해 +20%":""));double damage,interval;battle.AttackStats(unit,out damage,out interval);return name+" · 피해 "+Math.Round(damage,1)+" · 간격 "+Math.Round(interval,2)+"초"+((unit.Kind==1||unit.Kind==3)?" · "+PriorityName(unit.Priority):"");}
  void CyclePriority(Unit unit){int next=(unit.Priority+1)%4;if(battle.SetPriority(unit.Slot,next)){notice=Balance.Troops[unit.Kind].Name+" 목표: "+PriorityName(next);if(Debug.isDebugBuild&&Application.platform==RuntimePlatform.WebGLPlayer&&Application.absoluteURL.Contains("fx-smoke=priority"))Debug.Log("PRIORITY_SELECTED "+next);}}
  bool SpeedAvailable(){return battle.Phase==Phase.Fighting;}
  void ToggleQuickClear(){if(!battle.Decided||paused)return;quickClear=!quickClear;notice=quickClear?"빠른 소탕 · 6배속":"소탕 속도 복원";if(Debug.isDebugBuild&&Application.platform==RuntimePlatform.WebGLPlayer)Debug.Log("QUICK_CLEAR "+quickClear);}
