  Texture2D PlateTexture(string name){var source=Resources.Load<Texture2D>(name);if(source==null)return null;var plate=new Texture2D(100,96,TextureFormat.RGBA32,false);plate.filterMode=FilterMode.Point;plate.SetPixels(source.GetPixels(14,15,100,96));plate.Apply(false,true);return plate;}
